insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-26', 't-theories', 2, 'يستخدم معلم جدول تعزيز يكافئ الطالب بعد عدد غير ثابت من الاستجابات الصحيحة. هذا الجدول:', '["يجعل السلوك سريع الانطفاء","ينتج سلوكاً مقاوماً للانطفاء ومستمراً","لا يؤثر في السلوك","يصلح للعقاب فقط"]'::jsonb, 1, 'التعزيز المتقطع بنسبة متغيرة ينتج أعلى معدلات استجابة وأكثرها مقاومة للانطفاء مقارنة بالتعزيز المستمر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-27', 't-theories', 2, '«تشكيل السلوك (Shaping)» في النظرية السلوكية يعني:', '["تعزيز التقريبات المتتابعة نحو السلوك النهائي المطلوب","معاقبة كل خطأ حتى يختفي","تجاهل السلوك حتى ينطفئ","تقليد نموذج مباشرة"]'::jsonb, 0, 'التشكيل تعزيز الخطوات التي تقترب تدريجياً من السلوك الهدف حتى يتقنه المتعلم كاملاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-28', 't-theories', 3, 'وفق نموذج معالجة المعلومات، الفشل في استرجاع معلومة ذاكرها الطالب أمس يعزى غالباً إلى ضعف في:', '["الذاكرة الحسية","الترميز والتنظيم عند التخزين","حدة الإبصار","سرعة الكتابة"]'::jsonb, 1, 'جودة الترميز والتنظيم عند إدخال المعلومة للذاكرة طويلة المدى تحدد سهولة استرجاعها لاحقاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-29', 't-theories', 2, 'يطلب معلم من طلابه تقسيم رقم طويل إلى مجموعات صغيرة لتسهيل حفظه. هذه الاستراتيجية تسمى:', '["التجميع (التقطيع)","التسميع الآلي","الاسترجاع الحر","التعميم"]'::jsonb, 0, 'التجميع (Chunking) يقلل الحمل على الذاكرة العاملة محدودة السعة بدمج العناصر في وحدات أكبر ذات معنى.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tt-30', 't-theories', 3, 'صمم معلم درساً مزدحماً بالمؤثرات والألوان والأصوات فتشتت الطلاب وقلّ استيعابهم. المفهوم المفسر:', '["زيادة الحمل المعرفي على الذاكرة العاملة","نقص الدافعية الداخلية","ضعف التعزيز","التثبيت الوظيفي"]'::jsonb, 0, 'نظرية الحمل المعرفي: المؤثرات الدخيلة تستهلك سعة الذاكرة العاملة المحدودة على حساب معالجة المحتوى نفسه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-15', 't-growth', 2, 'وفق إريكسون، الأزمة النفسية الاجتماعية المميزة لمرحلة المراهقة هي:', '["الثقة مقابل عدم الثقة","المبادأة مقابل الشعور بالذنب","الهوية مقابل اضطراب الدور","التكامل مقابل اليأس"]'::jsonb, 2, 'يسعى المراهق لبناء هوية واضحة (من أنا؟ وماذا سأكون؟)، وفشل ذلك يؤدي لاضطراب الدور والتشتت.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-16', 't-growth', 2, 'طالب في الصف الثالث الابتدائي يقارن أعماله بأعمال زملائه ويحرص على إتقانها ليشعر بالكفاءة. وفق إريكسون هو في مرحلة:', '["المبادأة مقابل الذنب","الجد (الاجتهاد) مقابل الشعور بالنقص","الاستقلال مقابل الخجل","الألفة مقابل العزلة"]'::jsonb, 1, 'مرحلة الجد/الاجتهاد (6–12 سنة): يبني الطفل إحساسه بالكفاءة عبر الإنجاز المدرسي، وإخفاقه المتكرر يولّد شعوراً بالنقص.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-17', 't-growth', 3, 'طالب يمتنع عن الغش لأنه يرى أن الأمانة مبدأ يؤمن به لا خوفاً من العقاب. وفق كولبرج هذا يمثل المستوى:', '["ما قبل التقليدي","التقليدي","ما بعد التقليدي (المبدئي)","اللاأخلاقي"]'::jsonb, 2, 'المستوى ما بعد التقليدي يقوم على مبادئ أخلاقية داخلية مستقلة عن العقاب أو رضا الآخرين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-18', 't-growth', 2, 'طفل يمتنع عن السلوك الخاطئ خوفاً من العقاب فقط. وفق كولبرج هذا مستوى:', '["ما قبل التقليدي","التقليدي","ما بعد التقليدي","العقد الاجتماعي"]'::jsonb, 0, 'المستوى ما قبل التقليدي يرتبط الحكم الأخلاقي فيه بالنتائج المادية المباشرة: العقاب والمكافأة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-19', 't-growth', 2, 'أفضل ما يفعله المعلم مع طالب بطيء التعلم (قدراته أقل من المتوسط قليلاً وتحصيله متدنٍ):', '["مطالبته بمستوى الصف نفسه دون تعديل","تجزئة المهمة وإعطاء وقت أطول وتكرار بأمثلة محسوسة","استبعاده من الأنشطة الصفية","الاكتفاء بإبلاغ ولي أمره"]'::jsonb, 1, 'بطيء التعلم يحتاج تبسيطاً وتكراراً وأمثلة محسوسة ووقتاً إضافياً مع تعزيز مستمر، لا خفض التوقعات أو الإقصاء.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-20', 't-growth', 3, 'الفرق الجوهري بين «التأخر الدراسي» و«صعوبات التعلم»:', '["لا فرق بينهما","التأخر الدراسي عام وقد يرتبط بضعف القدرة أو ظروف بيئية، وصعوبات التعلم تباين حاد مع ذكاء عادي في مهارة محددة","صعوبات التعلم تعني انخفاض الذكاء","التأخر الدراسي لا يعالج"]'::jsonb, 1, 'صعوبات التعلم: ذكاء عادي فأعلى مع قصور نوعي في مهارة محددة. أما التأخر الدراسي فتدنٍ عام قد تسببه عوامل متعددة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-21', 't-growth', 2, 'طالبة متفوقة تتجنب المشاركة خوفاً من الخطأ أمام زميلاتها. أنسب تدخل من المعلمة:', '["إجبارها على الإجابة دائماً","بناء بيئة آمنة تُقبل فيها الأخطاء وتكليفها بمهام تدريجية تبني ثقتها","تجاهلها لأن مستواها جيد","مقارنتها بزميلاتها الجريئات"]'::jsonb, 1, 'الخوف من الخطأ يعالج بأمان نفسي ونجاحات متدرجة، لا بالإجبار أو المقارنة التي تزيد القلق.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-22', 't-growth', 2, '«القابلية للتعلم تزداد حين يبلغ المتعلم مستوى نضج عضوي وعقلي يمكّنه من المهارة». هذا المفهوم يسمى:', '["الاستعداد للتعلم","الدافعية","انتقال الأثر","التعزيز"]'::jsonb, 0, 'الاستعداد تهيؤ المتعلم نمائياً وخبراتياً لاكتساب مهارة، وتقديمها قبله يسبب إحباطاً وهدراً للجهد.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-19', 't-planning', 2, '«أن يصنّف الطالب الكلمات إلى أسماء وأفعال وحروف» — مستوى الهدف في تصنيف بلوم:', '["التذكر","التحليل","التقويم","الإبداع"]'::jsonb, 1, 'التصنيف يتطلب تفكيك العناصر وتمييز خصائصها وفق معيار، وهو من أفعال مستوى التحليل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-20', 't-planning', 2, '«أن يلتزم الطالب بآداب الحوار في المناقشات الصفية باستمرار» — يمثل مستوى في المجال الوجداني هو:', '["الاستقبال","الاستجابة","التمييز بالقيمة (الوسم)","التنظيم"]'::jsonb, 2, 'الالتزام الثابت المستمر الذي يصبح سمة في سلوك المتعلم هو أعلى مستويات المجال الوجداني (التمييز بالقيمة).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-21', 't-planning', 3, 'في تصميم الوحدة بالتخطيط العكسي (Backward Design)، يبدأ المعلم بـ:', '["اختيار الأنشطة الممتعة","تحديد نواتج التعلم المرغوبة وأدلة إتقانها ثم تصميم الأنشطة","ترتيب صفحات الكتاب","إعداد الواجبات"]'::jsonb, 1, 'التخطيط العكسي: نواتج التعلم أولاً، ثم أدلة التقويم المقبولة، وأخيراً خبرات التعلم التي توصل إليها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-22', 't-planning', 2, 'معلم خصص 12 حصة لوحدة من أصل 40 حصة للمقرر. الوزن النسبي لأسئلة هذه الوحدة في الاختبار النهائي:', '["12%","20%","30%","40%"]'::jsonb, 2, 'الوزن النسبي = (12 ÷ 40) × 100 = 30% من أسئلة الاختبار ودرجاته.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-23', 't-planning', 2, 'الغرض من تحليل المحتوى قبل التخطيط للتدريس:', '["اختصار زمن الحصة","تحديد المفاهيم والمهارات والقيم المتضمنة لبناء أهداف وأنشطة دقيقة","تقليل عدد الأنشطة","إلغاء التقويم"]'::jsonb, 1, 'تحليل المحتوى يفكك الدرس إلى مفاهيم وحقائق ومهارات وقيم، فتُبنى عليه الأهداف والأنشطة والتقويم بدقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-24', 't-planning', 3, 'ما المشكلة في هذا الهدف: «أن يشرح المعلم مراحل دورة الماء للطلاب»؟', '["لا مشكلة فيه","يصف سلوك المعلم لا ناتج تعلم المتعلم","فعله قابل للقياس أكثر من اللازم","يحتوي معياراً زائداً"]'::jsonb, 1, 'الهدف السلوكي يصف ما سيؤديه **المتعلم** بعد التعلم، لا ما سيفعله المعلم أثناء الشرح.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-21', 't-strategies', 2, 'استراتيجية يقسم فيها المحتوى إلى محطات موزعة في الصف تنتقل بينها المجموعات لأداء مهمة مختلفة عند كل محطة:', '["التعلم بالمحطات (الدوران)","المحاضرة","الكرسي الساخن","التسميع"]'::jsonb, 0, 'التعلم بالمحطات ينوّع المهام ويحرك الطلاب ويناسب التمايز وتعدد أنماط التعلم في الحصة الواحدة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-22', 't-strategies', 2, 'في استراتيجية «الرؤوس المرقمة معاً»، الهدف من ترقيم أفراد كل مجموعة:', '["ترتيب الجلوس فقط","ضمان المسؤولية الفردية إذ قد يُسأل أي رقم نيابة عن مجموعته","تسريع توزيع الأوراق","تحديد قائد دائم"]'::jsonb, 1, 'لأن أي رقم قد يُستدعى للإجابة، يحرص الجميع على فهم الحل — وهذا يحقق المحاسبة الفردية داخل العمل الجماعي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-23', 't-strategies', 3, 'أراد معلم دراسة قضية جدلية من زوايا متعددة (عاطفية، معلوماتية، إبداعية، نقدية، إيجابية، تنظيمية). الاستراتيجية الأنسب:', '["قبعات التفكير الست","التسميع الجماعي","الإملاء","المحاضرة"]'::jsonb, 0, 'قبعات دي بونو الست تنظم التفكير بفصل زواياه (البيضاء معلومات، الحمراء مشاعر، السوداء تحذير، الصفراء إيجابيات، الخضراء إبداع، الزرقاء تنظيم).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-24', 't-strategies', 2, 'استراتيجية «SQ3R» في القراءة تتضمن الخطوات:', '["التصفح، السؤال، القراءة، التسميع، المراجعة","الحفظ، النسخ، التكرار","الاستماع، الكتابة، الرسم","التلخيص فقط"]'::jsonb, 0, 'SQ3R: Survey (تصفح) وQuestion (تساؤل) وRead (قراءة) وRecite (تسميع) وReview (مراجعة) — تنمي الفهم القرائي المنظم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-25', 't-strategies', 2, 'عرض معلم مشكلة واقعية غير محددة الحل في بداية الوحدة ليبني الطلاب معارفهم أثناء سعيهم لحلها. هذا يسمى:', '["التعلم القائم على المشكلات (PBL)","التسميع","المحاضرة التفاعلية","التعلم المبرمج"]'::jsonb, 0, 'في التعلم القائم على المشكلات تكون المشكلة نقطة الانطلاق لا التطبيق الختامي، ويكتسب الطلاب المحتوى أثناء بحثهم عن الحل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-26', 't-strategies', 3, 'استخدم معلم «خرائط التفكير» ليقارن الطلاب بين ظاهرتين بإبراز أوجه الشبه والاختلاف بصرياً. الشكل الأنسب:', '["مخطط فن (الدائرتان المتقاطعتان)","السلم الزمني","المخطط الهرمي","مخطط السبب والنتيجة"]'::jsonb, 0, 'مخطط فن يعرض المشترك في التقاطع والمختلف في الأطراف، فهو الأنسب لمهام المقارنة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-27', 't-strategies', 2, 'معلم يوجه أسئلة متدرجة تقود الطلاب لاكتشاف القاعدة بأنفسهم دون إخبارهم بها. هذا الأسلوب:', '["الحوار السقراطي (الاستجوابي)","الإلقاء","التسميع","العرض العملي"]'::jsonb, 0, 'الحوار السقراطي يقود المتعلم بالأسئلة المتتابعة إلى بناء المعرفة واكتشاف التناقضات في تفكيره.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-28', 't-strategies', 2, 'من أبرز شروط نجاح الواجب المنزلي:', '["أن يكون طويلاً ليشغل وقت الطالب","أن يرتبط بأهداف الدرس ويكون واضحاً ومتدرجاً وتُقدَّم عليه تغذية راجعة","أن يُصحح دون تعليق","أن يكون موحداً للجميع دائماً"]'::jsonb, 1, 'الواجب الفعال هادف وواضح ومناسب الحجم، والأهم أن يتبعه تصحيح وتغذية راجعة وإلا فقد قيمته التعليمية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-29', 't-strategies', 3, 'يوظف معلم «التعلم بالخدمة المجتمعية» بتكليف الطلاب بمشروع توعية بترشيد المياه في الحي. أبرز ما ينميه:', '["الحفظ الآلي للمعلومات","ربط المحتوى الأكاديمي بالمسؤولية الاجتماعية والمواطنة","سرعة الكتابة","مهارات الاختبارات الموضوعية"]'::jsonb, 1, 'التعلم بالخدمة يدمج نواتج المنهج بخدمة حقيقية للمجتمع، فينمي المواطنة والمسؤولية مع ترسيخ المحتوى.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-30', 't-strategies', 2, 'لتحقيق التمايز في مخرجات التعلم (المنتجات)، يمكن للمعلم أن:', '["يفرض شكلاً واحداً للتسليم على الجميع","يتيح للطالب اختيار طريقة إظهار تعلمه (عرض، مطوية، فيديو، تقرير) وفق معايير موحدة","يلغي التقويم","يخفض المعايير للضعاف"]'::jsonb, 1, 'تمايز المنتجات يعني تنوع طرق إظهار التعلم مع ثبات معايير الجودة ونواتج التعلم المستهدفة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-23', 't-assessment', 2, 'اختبار يقيس قدرة الطالب على أداء مهارة في موقف حقيقي أو محاكٍ للواقع يسمى:', '["اختباراً تحريرياً موضوعياً","تقويماً أدائياً واقعياً","اختباراً شفهياً","تقويماً قبلياً"]'::jsonb, 1, 'التقويم الأدائي الواقعي يطلب أداءً فعلياً في سياق حقيقي (تجربة، عرض، مشروع) لا مجرد معرفة عنه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-24', 't-assessment', 3, 'معلم صحّح أوراق طلابه فتأثر بجودة خط الطالب فمنحه درجة أعلى مما يستحق في المضمون. هذا الخطأ يسمى:', '["أثر الهالة","خطأ النزعة المركزية","أثر التتابع","خطأ التساهل"]'::jsonb, 0, 'أثر الهالة: تعميم انطباع عن سمة واحدة (الخط، السلوك، سمعة الطالب) على تقدير سمات أخرى مستقلة عنها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-25', 't-assessment', 3, 'معلم يمنح معظم طلابه درجات متوسطة متقاربة ويتجنب الدرجات العالية والمنخفضة. هذا الخطأ في التقدير يسمى:', '["أثر الهالة","خطأ النزعة المركزية","خطأ التشدد","أثر الحداثة"]'::jsonb, 1, 'خطأ النزعة المركزية: تكدس التقديرات حول الوسط، فيفقد التقويم قدرته على التمييز بين المستويات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-26', 't-assessment', 2, 'لضمان موضوعية تصحيح الأسئلة المقالية، الإجراء الأفضل:', '["تصحيح كل ورقة كاملة قبل الانتقال لغيرها","إعداد نموذج إجابة بمعايير محددة وتصحيح السؤال نفسه لجميع الأوراق دفعة واحدة","التصحيح بالانطباع العام","معرفة اسم الطالب قبل التصحيح"]'::jsonb, 1, 'تصحيح السؤال ذاته عبر كل الأوراق مع نموذج إجابة محكّم يقلل أثر الهالة والتذبذب ويرفع ثبات التصحيح.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-27', 't-assessment', 2, '«اختبار يقيس ما إذا كان الطالب قد أتقن أهداف الوحدة قبل الانتقال للوحدة التالية». نوعه:', '["تشخيصي","تكويني/بنائي إتقاني","معياري المرجع","اختبار ذكاء"]'::jsonb, 1, 'التقويم التكويني الإتقاني يتحقق من بلوغ محك الإتقان أثناء التعلم قبل التقدم، ويتبعه علاج عند الحاجة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-28', 't-assessment', 3, 'سؤال معامل صعوبته 0.15 في اختبار تحصيلي عادي. الاستنتاج الصحيح:', '["السؤال سهل جداً","السؤال صعب جداً وأجاب عنه 15% فقط، ويحتاج مراجعة","السؤال مثالي","معامل التمييز مرتفع حتماً"]'::jsonb, 1, 'معامل الصعوبة نسبة من أجابوا صحيحاً؛ 0.15 يعني 15% فقط، وهو صعب جداً خارج المدى المفضل (0.3–0.7).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-29', 't-assessment', 2, 'أفضل وقت لتزويد الطالب بالتغذية الراجعة لتحقيق أثر تعليمي:', '["بعد شهر من الأداء","في أقرب وقت ممكن من الأداء","في نهاية العام الدراسي","لا حاجة لها"]'::jsonb, 1, 'فورية التغذية الراجعة تربط المعلومة التصحيحية بالأداء وهو حاضر في ذهن المتعلم، فيزداد أثرها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-30', 't-assessment', 3, 'معلم يريد قياس اتجاهات طلابه نحو مادة العلوم. الأداة الأنسب:', '["اختبار تحصيلي موضوعي","مقياس اتجاه متدرج (ليكرت)","اختبار أداء عملي","اختبار سرعة"]'::jsonb, 1, 'الاتجاهات من المجال الوجداني وتقاس بمقاييس التقدير المتدرجة كمقياس ليكرت، لا بالاختبارات التحصيلية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-31', 't-assessment', 2, 'من عيوب سؤال «الصواب والخطأ» مقارنة بالاختيار من متعدد:', '["صعوبة تصحيحه","ارتفاع احتمال التخمين إلى 50%","عدم صلاحيته للمحتوى المعرفي","استغراقه وقتاً طويلاً في الحل"]'::jsonb, 1, 'لوجود بديلين فقط يرتفع أثر التخمين إلى النصف، ما يخفض دقة القياس ما لم يكثر عدد الفقرات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-32', 't-assessment', 3, 'طبق معلم اختباراً على شعبتين، فجاءت درجات الشعبة (أ) متقاربة جداً حول المتوسط بينما تباينت درجات (ب) بوضوح. الاختبار في الشعبة (ب) كان أكثر:', '["صدقاً","تمييزاً بين المستويات","سهولة","ثباتاً"]'::jsonb, 1, 'التباين في الدرجات مؤشر على قدرة الاختبار على التمييز بين مستويات الطلاب، بخلاف تكدس الدرجات.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-15', 't-classroom', 2, 'طالب يضع رأسه على الطاولة ويمتنع عن المشاركة منذ بداية الحصة. أفضل بداية للمعالجة:', '["توبيخه أمام الصف","الاقتراب منه بهدوء والسؤال عن حاله لمعرفة السبب قبل الحكم","خصم درجات المشاركة فوراً","إخراجه من الصف"]'::jsonb, 1, 'السلوك عرض قد يخفي مرضاً أو مشكلة نفسية أو أسرية؛ فهم السبب يسبق أي إجراء تأديبي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-16', 't-classroom', 3, 'مفهوم «الوعي الشامل بالصف (Withitness)» عند كاونين يعني:', '["حفظ أسماء الطلاب","إدراك المعلم لما يجري في أرجاء الصف كافة والتدخل المبكر الدقيق","الإكثار من العقاب","الالتزام بالكتاب حرفياً"]'::jsonb, 1, 'المعلم «الواعي شمولياً» يلحظ بوادر المشكلات مبكراً ويتدخل بدقة قبل تفاقمها، فتقل المشكلات الصفية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-17', 't-classroom', 2, '«التداخل (Overlapping)» في إدارة الصف يعني قدرة المعلم على:', '["إعطاء درسين في وقت واحد","معالجة موقف سلوكي دون توقف سير التعلم","دمج مادتين في حصة","تكرار الشرح مرتين"]'::jsonb, 1, 'التداخل مهارة التعامل مع أكثر من موقف آنياً — كضبط سلوك جانبي مع استمرار الشرح — فيحافظ على زخم الدرس.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-18', 't-classroom', 2, 'مجموعة في التعلم التعاوني تعتمد على طالب واحد ينجز العمل بينما يكتفي البقية بالمشاهدة. المعالجة الأنسب:', '["إلغاء العمل التعاوني نهائياً","توزيع أدوار محددة لكل فرد وتقويم فردي إلى جانب الجماعي","معاقبة المجموعة كلها","السماح باستمرار الوضع"]'::jsonb, 1, 'ظاهرة «التطفل الاجتماعي» تعالج بالأدوار المحددة والمحاسبة الفردية التي تجعل مساهمة كل فرد مرئية ومقوَّمة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-19', 't-classroom', 2, 'من أفضل الممارسات في بداية الحصة لتقليل الوقت المهدور:', '["الانتظار حتى يهدأ الجميع تماماً مهما طال","روتين افتتاحي ثابت ومهمة تحفيزية قصيرة يبدؤها الطلاب فور دخولهم","توبيخ المتأخرين طويلاً","مراجعة الغياب بتفصيل"]'::jsonb, 1, 'المهمة الافتتاحية الجاهزة تشغل الطلاب فوراً وتقلل الفراغ الذي تنشأ فيه المشكلات، وتوفر زمن التعلم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tc-20', 't-classroom', 3, 'طالب يعاني ضعفاً في التحصيل ويثير الفوضى كلما طُلب منه حل تمرين. التفسير الأرجح لسلوكه:', '["حب الظهور فقط","تجنب المهمة هرباً من الشعور بالفشل أمام زملائه","سوء تربية أسرية حتماً","اضطراب عقلي"]'::jsonb, 1, 'كثير من سلوكيات التعطيل وظيفتها الهروب من مهمة يخشى المتعلم الفشل فيها؛ فالعلاج تكييف صعوبة المهمة وبناء النجاح المتدرج.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
